  inline const LQIConfigStatics *LQIConfig::__get_statics__()
  {
    const static LQIConfigStatics *statics;

    if (statics) // Common case
      return statics;

    boost::mutex::scoped_lock lock(dynamic_reconfigure::__init_mutex__);

    if (statics) // In case we lost a race.
      return statics;

    statics = LQIConfigStatics::get_instance();

    return statics;
  }


